#!/usr/bin/env python3
"""Generate /root/project_proposal_ready.hwpx from the template + JSON.

Contract (task):
- Replace all {{...}} placeholders with values from project_proposal.json
- Budget numeric part: remove commas (keep currency symbol)
- Phase lines: append computed month span " (N개월)" after the existing date part
- For any paragraph whose text was modified: remove stale layout-cache elements
  like <hp:linesegarray> / <hp:lineSegArray>
- Output must be a valid .hwpx ZIP package

Notes:
- HWPX is a zip of XML parts (similar to docx). This template is intentionally
  minimal, but we still implement a robust per-paragraph text-run replacement to
  handle placeholders split across multiple <hp:t> nodes.
"""

from __future__ import annotations

import json
import re
import zipfile
from pathlib import Path

TEMPLATE_PATH = Path("/root/project_proposal_template.hwpx")
JSON_PATH = Path("/root/project_proposal.json")
OUT_PATH = Path("/root/project_proposal_ready.hwpx")


def normalize_budget(value: str) -> str:
    # Remove commas only when they are digit separators.
    return re.sub(r"(?<=\d),(?=\d)", "", value)


_DATE_RANGE_RE = re.compile(
    r"(?P<sy>\d{4})[./-]?(?P<sm>\d{2})\s*~\s*(?P<ey>\d{4})[./-]?(?P<em>\d{2})"
)
_SINGLE_MONTH_RE = re.compile(r"(?P<y>\d{4})[./-]?(?P<m>\d{2})")


def months_inclusive(start_y: int, start_m: int, end_y: int, end_m: int) -> int:
    return (end_y - start_y) * 12 + (end_m - start_m) + 1


def compute_phase_months(text: str) -> int | None:
    """Compute month span from a text containing a date range.

    Accepts either:
    - YYYY-MM ~ YYYY-MM (or YYYY.MM)
    - YYYY-MM (single month)

    Returns None if no recognizable date exists.
    """
    m = _DATE_RANGE_RE.search(text)
    if m:
        sy, sm, ey, em = int(m["sy"]), int(m["sm"]), int(m["ey"]), int(m["em"])
        return months_inclusive(sy, sm, ey, em)

    # Single-month (e.g. "(2027-01)")
    m2 = _SINGLE_MONTH_RE.search(text)
    if m2:
        return 1

    return None


def try_import_lxml():
    try:
        from lxml import etree  # type: ignore

        return etree
    except Exception:
        return None


def localname(tag: str) -> str:
    # '{ns}name' -> 'name'
    if tag.startswith("{"):
        return tag.rsplit("}", 1)[1]
    return tag


def remove_lineseg_cache(paragraph_el) -> int:
    """Remove line-seg cache elements under a paragraph element.

    Returns number of removed elements.
    """
    removed = 0

    # Remove any descendant whose localname contains 'lineseg'
    # (covers: linesegarray, lineSegArray, etc.)
    for el in list(paragraph_el.iter()):
        if el is paragraph_el:
            continue
        ln = localname(el.tag).lower()
        if "lineseg" in ln:
            parent = el.getparent() if hasattr(el, "getparent") else None
            if parent is None:
                # xml.etree doesn't support getparent; handled in ET branch.
                continue
            parent.remove(el)
            removed += 1
    return removed


def remove_lineseg_cache_et(paragraph_el) -> int:
    """xml.etree fallback: remove line-seg cache elements without getparent()."""
    removed = 0

    def _walk(parent):
        nonlocal removed
        for child in list(parent):
            ln = localname(child.tag).lower()
            if "lineseg" in ln:
                parent.remove(child)
                removed += 1
            else:
                _walk(child)

    _walk(paragraph_el)
    return removed


def main() -> None:
    data = json.loads(JSON_PATH.read_text(encoding="utf-8"))

    # Pre-normalize budget field if present.
    # The template uses Korean key names, but we keep this generic.
    normalized = {}
    for k, v in data.items():
        if isinstance(v, str) and (k in {"예산", "budget", "총예산"} or "예산" in k):
            normalized[k] = normalize_budget(v)
        else:
            normalized[k] = v

    etree = try_import_lxml()

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        names = zin.namelist()
        out_bytes: dict[str, bytes] = {}

        for name in names:
            raw = zin.read(name)

            if not name.lower().endswith(".xml"):
                out_bytes[name] = raw
                continue

            xml_text = raw.decode("utf-8", errors="strict")

            # Quick path: if there are no placeholders and no phase markers,
            # still ensure we leave it untouched.
            if "{{" not in xml_text and "단계" not in xml_text and "lineseg" not in xml_text.lower():
                out_bytes[name] = raw
                continue

            if etree is not None:
                parser = etree.XMLParser(remove_blank_text=False, resolve_entities=False)
                root = etree.fromstring(raw, parser)

                modified_any = False
                modified_paragraph_ids: set[str] = set()

                nsmap = root.nsmap.copy() if hasattr(root, "nsmap") else {}
                hp_ns = nsmap.get("hp") or "http://www.hancom.co.kr/hwpml/2010/HWPML"

                # Iterate paragraphs; operate at paragraph-level to handle split placeholders.
                for p in root.findall(f".//{{{hp_ns}}}p"):
                    t_elems = p.findall(f".//{{{hp_ns}}}t")
                    if not t_elems:
                        continue

                    original = "".join([t.text or "" for t in t_elems])
                    new = original

                    # Placeholder replacements
                    for k, v in normalized.items():
                        if not isinstance(v, str):
                            v = str(v)
                        new = new.replace("{{" + k + "}}", v)

                    # Phase month span appending
                    if re.search(r"\b[123]단계\s*:", new) and "개월" not in new:
                        months = compute_phase_months(new)
                        if months is not None:
                            new = new + f" ({months}개월)"

                    if new != original:
                        modified_any = True
                        pid = p.get("id")
                        if pid is not None:
                            modified_paragraph_ids.add(pid)

                        # Put full new text into first run, blank out the rest.
                        t_elems[0].text = new
                        for t in t_elems[1:]:
                            t.text = ""

                # Strip stale layout cache from modified paragraphs only
                if modified_paragraph_ids:
                    for p in root.findall(f".//{{{hp_ns}}}p"):
                        pid = p.get("id")
                        if pid is not None and pid in modified_paragraph_ids:
                            remove_lineseg_cache(p)

                out_xml = etree.tostring(
                    root,
                    xml_declaration=True,
                    encoding="utf-8",
                    standalone=None,
                )

                if b"{{" in out_xml:
                    raise SystemExit(f"Unreplaced placeholder remains in {name}")

                out_bytes[name] = out_xml

            else:
                # Fallback: xml.etree.ElementTree (slightly less capable)
                import xml.etree.ElementTree as ET

                root = ET.fromstring(raw)

                # Find hp namespace from root tag if present
                m = re.match(r"\{([^}]+)\}", root.tag)
                hp_ns = m.group(1) if m else "http://www.hancom.co.kr/hwpml/2010/HWPML"

                modified_paragraphs = set()

                for p in root.findall(f".//{{{hp_ns}}}p"):
                    t_elems = p.findall(f".//{{{hp_ns}}}t")
                    if not t_elems:
                        continue

                    original = "".join([t.text or "" for t in t_elems])
                    new = original

                    for k, v in normalized.items():
                        if not isinstance(v, str):
                            v = str(v)
                        new = new.replace("{{" + k + "}}", v)

                    if re.search(r"\b[123]단계\s*:", new) and "개월" not in new:
                        months = compute_phase_months(new)
                        if months is not None:
                            new = new + f" ({months}개월)"

                    if new != original:
                        pid = p.get("id")
                        modified_paragraphs.add(pid if pid is not None else id(p))
                        t_elems[0].text = new
                        for t in t_elems[1:]:
                            t.text = ""

                # Remove cache elements from modified paragraphs
                for p in root.findall(f".//{{{hp_ns}}}p"):
                    pid = p.get("id")
                    key = pid if pid is not None else id(p)
                    if key in modified_paragraphs:
                        remove_lineseg_cache_et(p)

                out_xml = ET.tostring(root, encoding="utf-8", xml_declaration=True)
                if b"{{" in out_xml:
                    raise SystemExit(f"Unreplaced placeholder remains in {name}")
                out_bytes[name] = out_xml

        # Write new zip
        with zipfile.ZipFile(OUT_PATH, "w", compression=zipfile.ZIP_DEFLATED) as zout:
            for name in names:
                zout.writestr(name, out_bytes[name])

    # Basic validation: zip is readable and no placeholders remain anywhere
    if not zipfile.is_zipfile(OUT_PATH):
        raise SystemExit("Output is not a valid zip")

    with zipfile.ZipFile(OUT_PATH, "r") as z:
        for name in z.namelist():
            if name.lower().endswith(".xml"):
                txt = z.read(name).decode("utf-8", errors="replace")
                if "{{" in txt:
                    raise SystemExit(f"Placeholder left in output: {name}")


if __name__ == "__main__":
    main()

